func bowyer_watson(points) = {
  local n = points.listLen()
  local bigT = 1000
  local superTri = [[-bigT,-bigT],[bigT,-bigT],[0,bigT*2]]
  local triangles = [[1,2,3]]
  local allPts = copyList(superTri)
  for (p in points) { allPts.add(p) }
  for (pi: 4 .. allPts.listLen()) {
    local pt = allPts[pi]
    local badTris = []
    local goodTris = []
    for (tri in triangles) {
      local ax = allPts[tri[1]][1]
      local ay = allPts[tri[1]][2]
      local bx = allPts[tri[2]][1]
      local by = allPts[tri[2]][2]
      local cx = allPts[tri[3]][1]
      local cy = allPts[tri[3]][2]
      local D = 2*(ax*(by-cy)+bx*(cy-ay)+cx*(ay-by))
      if (abs(D) < 0.0001) {
        goodTris.add(tri)
      } else {
        local ux = ((ax*ax+ay*ay)*(by-cy)+(bx*bx+by*by)*(cy-ay)+(cx*cx+cy*cy)*(ay-by))/D
        local uy = ((ax*ax+ay*ay)*(cx-bx)+(bx*bx+by*by)*(ax-cx)+(cx*cx+cy*cy)*(bx-ax))/D
        local dx = pt[1]-ux
        local dy = pt[2]-uy
        local r2 = (ax-ux)*(ax-ux)+(ay-uy)*(ay-uy)
        if (dx*dx+dy*dy < r2) { badTris.add(tri) } else { goodTris.add(tri) }
      }
    }
    local boundary = []
    for (bt in badTris) {
      local edges = [[bt[1],bt[2]],[bt[2],bt[3]],[bt[3],bt[1]]]
      for (e in edges) {
        local shared = false
        for (bt2 in badTris) {
          if (bt2 !== bt) {
            local edges2 = [[bt2[1],bt2[2]],[bt2[2],bt2[3]],[bt2[3],bt2[1]]]
            for (e2 in edges2) {
              if ((e[1]==e2[1]&&e[2]==e2[2])||(e[1]==e2[2]&&e[2]==e2[1])) { shared = true }
            }
          }
        }
        if (!shared) { boundary.add(e) }
      }
    }
    triangles = goodTris
    for (e in boundary) {
      triangles.add([e[1], e[2], pi])
    }
  }
  local finalTris = []
  for (tri in triangles) {
    if (tri[1] <= 3 || tri[2] <= 3 || tri[3] <= 3) {
    } else {
      finalTris.add([tri[1]-3, tri[2]-3, tri[3]-3])
    }
  }
  finalTris
}
println(bowyer_watson([[0,0],[1,0],[0,1],[1,1]]))

